import { Request, Response, Router } from 'express';
import { CreateProjectUseCase } from '../../../application/use-cases/CreateProjectUseCase';
import { CreateTaskUseCase } from '../../../application/use-cases/CreateTaskUseCase';
import { ListProjectTasksUseCase } from '../../../application/use-cases/ListProjectTasksUseCase';
import { BadRequestError, optionalString, readBody, requiredString } from '../RequestParsing';

function queryString(req: Request, field: string): string | undefined {
  const value = req.query[field];
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== 'string') {
    throw new BadRequestError(`Query parameter "${field}" must be a single string`);
  }
  return value;
}

export class ProjectController {
  constructor(
    private readonly createProject: CreateProjectUseCase,
    private readonly createTask: CreateTaskUseCase,
    private readonly listProjectTasks: ListProjectTasksUseCase,
  ) {}

  routes(): Router {
    const router = Router();
    router.post('/projects', (req, res) => this.create(req, res));
    router.post('/projects/:projectId/tasks', (req, res) => this.addTask(req, res));
    router.get('/projects/:projectId/tasks', (req, res) => this.listTasks(req, res));
    return router;
  }

  async create(req: Request, res: Response): Promise<void> {
    const body = readBody(req.body);
    const project = await this.createProject.execute({ name: requiredString(body, 'name') });
    res.status(201).json(project);
  }

  async addTask(req: Request, res: Response): Promise<void> {
    const body = readBody(req.body);
    const task = await this.createTask.execute({
      projectId: String(req.params.projectId),
      title: requiredString(body, 'title'),
      description: optionalString(body, 'description') ?? '',
      dueDate: optionalString(body, 'dueDate'),
      status: optionalString(body, 'status'),
    });
    res.status(201).json(task);
  }

  async listTasks(req: Request, res: Response): Promise<void> {
    const tasks = await this.listProjectTasks.execute({
      projectId: String(req.params.projectId),
      status: queryString(req, 'status'),
      assigneeId: queryString(req, 'assigneeId'),
    });
    res.json(tasks);
  }
}

